import React from 'react';
import { motion } from 'framer-motion';

const Skills = () => {
  const skillCategories = [
    {
      area: "Development",
      list: ["React.js", "Next.js", "Node.js", "Express", "FastAPI", "Tailwind CSS", "MERN Stack"]
    },
    {
      area: "Intelligence",
      list: ["Python", "Machine Learning", "NLP", "Scikit-learn", "Data Modeling"]
    },
    {
      area: "Foundations",
      list: ["C++", "Data Structures", "Algorithms", "SQL", "MongoDB", "PostgreSQL"]
    },
    {
      area: "Engineering",
      list: ["Git/GitHub", "Docker", "REST APIs", "System Design", "UI/UX"]
    }
  ];

  return (
    <section id="skills" className="py-32 px-6 md:px-10 bg-white relative overflow-hidden">
      <div className="container mx-auto max-w-7xl">

        {/* Section Header */}
        <div className="relative mb-24">
          <h2 className="text-[12vw] font-black text-gray-50 absolute -top-16 left-0 leading-none select-none uppercase tracking-tighter">
            STACK
          </h2>
          <h3 className="text-5xl font-black relative z-10 tracking-tighter text-gray-900 leading-tight">
            MY TECHNICAL <br/> <span className="text-blue-600 italic">ARSENAL.</span>
          </h3>
        </div>

        {/* Skills Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12 relative z-10">
          {skillCategories.map((category, index) => (
            <motion.div 
              key={index}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
              viewport={{ once: true }}
              className="flex flex-col gap-6"
            >
              <h4 className="text-xs font-black uppercase tracking-[0.3em] text-gray-400 border-l-2 border-blue-600 pl-4">
                {category.area}
              </h4>

              <div className="flex flex-wrap gap-3">
                {category.list.map((skill, i) => (
                  <motion.span 
                    key={i}
                    whileHover={{ scale: 1.05, backgroundColor: "#000", color: "#fff" }}
                    className="px-5 py-2.5 bg-gray-50 border border-gray-100 rounded-full text-sm font-bold text-gray-800 transition-all cursor-default shadow-sm"
                  >
                    {skill}
                  </motion.span>
                ))}
              </div>
            </motion.div>
          ))}
        </div>

        {/* Subtle Bottom Accent */}
        <div className="mt-32 pt-10 border-t border-gray-50 flex flex-col md:flex-row justify-between items-center gap-6">
          <p className="text-gray-400 font-bold text-sm tracking-tight">
            Continually evolving with new technologies and frameworks.
          </p>
          <div className="flex gap-4">
            <div className="w-2 h-2 rounded-full bg-blue-600 animate-pulse"></div>
            <div className="w-2 h-2 rounded-full bg-blue-400 animate-pulse delay-75"></div>
            <div className="w-2 h-2 rounded-full bg-blue-200 animate-pulse delay-150"></div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Skills;
